def main() -> int:
    notes = read_notes_only(DKAB_SOURCE)
    existing = [json.loads(x) for x in OUTPUT.read_text(encoding="utf-8").splitlines() if x.strip()]
    if len(existing) != 400:
        raise RuntimeError("validated first four batches must exist before batch 05")
    labels = json.loads(LABELS_OUTPUT.read_text(encoding="utf-8"))
    visits: dict[tuple[int, str], int] = {}
    rows = []
    for local, (mode, level) in enumerate(zip(MODE_SEQUENCE, LEVEL_SEQUENCE), 1):
        index = (local - 1) % len(CASES)
        key = (index, mode)
        case = contextual_case(CASES[index], mode, visits.get(key, 0))
        visits[key] = visits.get(key, 0) + 1
        rows.append(make_question(
            local, case, mode, level, notes[case[0]], labels,
            "Din Kültürü ve Ahlak Bilgisi", batch_number=5, number_base=400,
        ))
    OUTPUT.write_text("\n".join(json.dumps(row, ensure_ascii=False, separators=(",", ":")) for row in existing + rows) + "\n", encoding="utf-8", newline="\n")
    LABELS_OUTPUT.write_text(json.dumps(labels, ensure_ascii=False, sort_keys=True, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps({"batch": 5, "questions": 100, "religion": 100, "total": 500, "labels": len(labels), "sourceQuestionReads": 0}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
